<template>
  <div ref="editor" style="height: 500px; width: 100%"></div>
</template>

<script lang="ts">
import ace from 'ace-builds';
import 'ace-builds/src-noconflict/mode-json';
import 'ace-builds/src-noconflict/theme-monokai';
import { defineComponent, ref, PropType } from 'vue';
import { notify } from 'src/components/notifications/notify';

ace.config.setModuleUrl(
  'ace/mode/json_worker',
  'https://cdnjs.cloudflare.com/ajax/libs/ace/1.4.14/worker-json.js',
);

export default defineComponent({
  name: 'layout-json-editor',
  props: {
    jsonData: {
      type: Object as PropType<Record<string, any>>,
      required: true,
    },
  },
  data() {
    return {
      formattedJson: ref(''), // Using ref for reactive data
      editorInstance: null as any,
    };
  },
  mounted() {
    this.prepareJsonToDisplay();
    this.initializeEditor();
  },
  beforeUnmount() {
    if (this.editorInstance) {
      this.editorInstance.destroy();
    }
  },
  methods: {
    initializeEditor() {
      if (this.$refs.editor) {
        // Initialize Ace Editor
        this.editorInstance = ace.edit(this.$refs.editor as HTMLDivElement, {
          mode: 'ace/mode/json',
          theme: 'ace/theme/monokai',
          value: this.formattedJson,
          wrap: true,
        });
        this.editorInstance.session.setUseWorker(false);

        // Update formattedJson whenever the editor content changes
        // this.editorInstance.session.on('change', this.beautifyJson);
        this.editorInstance.on('paste', () => {
          setTimeout(() => {
            this.beautifyJson();
          }, 100); // Give a short delay to allow the paste action to complete
        });
      }
    },
    beautifyJson() {
      const currentContent = this.getJson();
      try {
        // Attempt to parse and beautify the JSON
        if (!currentContent) {
          return;
        }
        const parsedJson = JSON.parse(currentContent);
        const beautifiedJson = JSON.stringify(parsedJson, null, 4);
        this.formattedJson = beautifiedJson;
        this.editorInstance.setValue(beautifiedJson, -1); // Set the beautified JSON in the editor
      } catch (error) {
        // If parsing fails, do nothing or show an error if needed
        logError(error);
        // notify.error('Invalid JSON, unable to beautify');
      }
    },
    prepareJsonToDisplay() {
      // Format the initial JSON data to a readable format
      this.formattedJson = JSON.stringify(this.jsonData, null, 4);
    },
    getJson(): any {
      // Retrieve the current JSON data from the editor
      return this.editorInstance ? this.editorInstance.getValue() : '';
    },
  },

  setup() {
    return {};
  },
});
</script>
